export function SafraLogo({
  variant = 'inline',
  lang = 'ar',
  height = 34,
  title,
  ...rest
}: SafraLogoProps) {
  const key: ArtKey =
    variant === 'inline' || variant === 'stacked'
      ? (`${variant}-${lang}` as const)
      : variant === 'wordmark'
        ? 'wordmark-ar'
        : variant;
  const art = ART[key];
  const label = title ?? (lang === 'ar' ? 'سفرة' : 'SAFRA');
  return (
    <svg
      viewBox={`0 0 ${art.w} ${art.h}`}
      height={height}
      width={(height * art.w) / art.h}
      role={label ? 'img' : undefined}
      aria-label={label || undefined}
      aria-hidden={label ? undefined : true}
      {...rest}
    >
      {label ? <title>{label}</title> : null}
      {art.body}
    </svg>
  );
}
